sections.body:
保存为 rollout-audit.mjs，运行 node rollout-audit.mjs，无额外依赖。actual 是本例的权威规则；model 故意没有墙；hybrid 在模型之后加入已知边界。三个函数都返回新数值，不修改游戏对象。代码中的空间限制与循环上限用于约束教学输入。

```js
/**
 * @file Learn a scalar movement model and audit one-step versus free rollouts.
 * @author liliwei
 * @date 2026-11-07
 * @LastEditors liliwei
 * @LastEditTime 2026-11-07
 */
import assert from 'node:assert/strict';

/** Check the toy model's inputs. @param {number} x Position. @param {number} a Action. @returns {void} */
function check(x, a) {
  assert(Number.isFinite(x) && Math.abs(x) <= 1e6);
  assert([-1, 0, 1].includes(a));
}
/** Advance the authoritative toy corridor. @param {number} x Position in [0,10]. @param {number} a Action. @returns {number} Next position. */
export function actual(x, a) {
  check(x, a); assert(x >= 0 && x <= 10);
  return Math.max(0, Math.min(10, x + 0.5 * a));
}
/** Fit deltaX = k * action without an intercept. @param {Array<{x:number,a:number,next:number}>} rows Training transitions. @returns {number} Fitted coefficient. */
export function fit(rows) {
  assert(Array.isArray(rows) && rows.length > 0);
  let numerator = 0, denominator = 0;
  for (const row of rows) {
    assert(row && typeof row === 'object');
    const { x, a, next } = row;
    check(x, a); assert(x >= 0 && x <= 10);
    assert(Number.isFinite(next) && next >= 0 && next <= 10);
    numerator += a * (next - x); denominator += a * a;
  }
  assert(denominator > 0 && Number.isFinite(numerator));
  return numerator / denominator;
}
/** Roll out a supplied transition. @param {Function} step Next-position function. @param {number} start Initial position. @param {number[]} actions Frozen controls. @returns {number[]} Positions including the initial state. */
export function rollout(step, start, actions) {
  check(start, 0); assert(Array.isArray(actions) && actions.length <= 1000);
  const states = [start];
  for (const a of actions) {
    check(states.at(-1), a);
    const next = step(states.at(-1), a); check(next, 0); states.push(next);
  }
  return states;
}

const train = [1, 3, 5, 7].flatMap(x =>
  [-1, 1].map(a => ({ x, a, next: actual(x, a) })));
export const k = fit(train);
/** Predict without a wall rule. @param {number} x Current or imagined position. @param {number} a Action. @returns {number} Unconstrained prediction. */
export function model(x, a) { check(x, a); return x + k * a; }
/** Add the known corridor constraint. @param {number} x Position. @param {number} a Action. @returns {number} Rule-constrained prediction. */
export function hybrid(x, a) { return Math.max(0, Math.min(10, model(x, a))); }

const actions = Array(8).fill(1);
const truth = rollout(actual, 8, actions);
const imagined = rollout(model, 8, actions);
const corrected = rollout(hybrid, 8, actions);
const oneStep = actions.map((a, i) => model(truth[i], a));
const rmse = Math.sqrt(oneStep.reduce((sum, x, i) =>
  sum + (x - truth[i + 1]) ** 2, 0) / actions.length);
console.log(JSON.stringify({ k, truth, imagined, corrected, oneStepRMSE: rmse,
  horizonErrors: [1, 4, 8].map(h => ({ h, error: Math.abs(imagined[h] - truth[h]) })) }, null, 2));
```

oneStep 每次从 truth[i] 出发；imagined 只在开头得到真实起点，以后使用自己的上一项预测。这是两种不同任务。预测越界暂时保留下来，便于暴露错误；它从未写回真实游戏状态。

hybrid 的墙是开发者明确写入的知识，不是模型突然学会了碰撞。对于这个已经完全知道规则的小场景，直接使用 actual 就足够；练习价值在于先验收未来更复杂、确实需要学习的预测器。
